<?php
if(!function_exists('render_signed_header')){
function render_signed_header(array $user,string $context='',string $subtitle='',bool $genreTheme=false):void{?>
<header class="signed-header <?=$genreTheme?'signed-header-genre':''?>"><div class="signed-header-inner"><div class="signed-brand"><a class="toinky-brand" href="./?view=public" aria-label="Open Toinky homepage"><span class="toinky-logo-mark" role="img" aria-label="Toinky"></span></a><?php if($context!==''):?><span class="signed-context">| <?=e(mb_strtoupper($context))?></span><?php endif;?><?php if($subtitle!==''):?><span class="signed-subtitle"><?=e($subtitle)?></span><?php endif;?></div><nav class="signed-nav" aria-label="Account navigation"><span class="signed-hello">Hello, <?=e($user['display_name'])?></span><a href="./">My Games</a><a href="profile.php">My Profile</a><?php if((int)($user['is_admin']??0)===1):?><a href="admin.php">Admin</a><?php endif;?><?php if((int)($user['is_admin']??0)===1||AuthService::hasRole((int)$user['user_id'],'WRITER')):?><a href="writer.php">Story Writer</a><?php endif;?><form method="post" action="./"><input type="hidden" name="csrf_token" value="<?=e(AuthService::csrfToken())?>"><input type="hidden" name="action" value="logout"><button type="submit">Sign Out</button></form></nav></div></header>
<?php }}
